import time
import subprocess
from datetime import datetime

def monitor_connections(host: str, interval_s: int) -> list[dict]:
    connections = []
    while True:
        try:
            result = subprocess.run(['netstat', '-tuln'], capture_output=True, text=True)
            connections_str = result.stdout.split('\n')[2:]  # Skip header lines
            for conn in connections_str:
                if conn.strip():
                    parts = conn.split()
                    if len(parts) >= 4:
                        timestamp = datetime.now().isoformat()
                        source = parts[3].split(':')[0]
                        connection_info = {
                            'timestamp': timestamp,
                            'host': host,
                            'source': source,
                            'connection': conn.strip()
                        }
                        connections.append(connection_info)
            time.sleep(interval_s)
        except KeyboardInterrupt:
            break
    return connections
```

