import hashlib

def anonymize_dataset(records: list[dict], fields: list[str]) -> list[dict]:
    anonymized_records = []
    for record in records:
        anonymized_record = record.copy()
        for field in fields:
            if field in anonymized_record and anonymized_record[field]:
                # Anonymize by hashing the value
                anonymized_record[field] = hashlib.sha256(
                    str(anonymized_record[field]).encode()
                ).hexdigest()
        anonymized_records.append(anonymized_record)
    return anonymized_records
