from collections import defaultdict

def detect_brute_force(auth_log: list[dict], threshold: int = 5) -> list[str]:
    ip_attempts = defaultdict(int)

    for entry in auth_log:
        if not entry.get('success'):
            ip = entry.get('ip')
            if ip:
                ip_attempts[ip] += 1

    return [ip for ip, attempts in ip_attempts.items() if attempts >= threshold]
```

