import dpkt
import socket
from collections import defaultdict

def analyze_dns_traffic(pcap_file: str) -> dict:
    suspicious_domains = defaultdict(list)
    dns_queries = []

    with open(pcap_file, 'rb') as f:
        pcap = dpkt.pcap.Reader(f)
        for timestamp, buf in pcap:
            eth = dpkt.ethernet.Ethernet(buf)
            if not isinstance(eth.data, dpkt.ip.IP):
                continue
            ip = eth.data
            if isinstance(ip.data, dpkt.tcp.TCP):
                tcp = ip.data
                if tcp.dport == 53 or tcp.sport == 53:  # DNS port
                    dns = dpkt.dns.DNS(tcp.data)
                    if dns.qr == dpkt.dns.DNS_Q:  # Query
                        for query in dns.qd:
                            domain = query.name.decode('utf-8').rstrip('.')
                            dns_queries.append(domain)
                            if is_suspicious(domain):
                                suspicious_domains['dga'].append(domain)
                            if is_tunneling(domain):
                                suspicious_domains['tunneling'].append(domain)
                            if is_exfiltration(domain):
                                suspicious_domains['exfiltration'].append(domain)

    return dict(suspicious_domains)

def is_suspicious(domain: str) -> bool:
    # Simple heuristic for DGA domains
    return len(domain) > 20 or not any(c.isalpha() for c in domain)

def is_tunneling(domain: str) -> bool:
    # Simple heuristic for DNS tunneling
    return domain.count('.') > 5 or any(c in domain for c in ['=', ':', '/'])

def is_exfiltration(domain: str) -> bool:
    # Simple heuristic for data exfiltration
    return any(c in domain for c in ['@', '|', '#'])
